const rawItems = $input.all();
const seen = new Set();
const domains = [];

const pushDomain = (val) => {
  if (!val || typeof val !== 'string') return;
  let cleaned = val.trim().toLowerCase();
  cleaned = cleaned.replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0].trim();
  if (!cleaned || !cleaned.includes('.') || cleaned.includes(' ')) return;
  if (!seen.has(cleaned)) {
    seen.add(cleaned);
    domains.push(cleaned);
  }
};

for (const item of rawItems) {
  const body = item.json?.body ?? item.json;
  if (Array.isArray(body?.domains)) {
    for (const d of body.domains) pushDomain(d);
  } else if (typeof body?.website === 'string') {
    pushDomain(body.website);
  } else if (typeof body?.domain === 'string') {
    pushDomain(body.domain);
  } else if (typeof body?.url === 'string') {
    pushDomain(body.url);
  }
}

if (domains.length === 0) {
  return [];
}

return [{
  json: {
    domains,
    count: domains.length
  }
}];

const rows = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r || r.status !== 'enriched' || !r.domain) continue;

  const verifiedDms = Array.isArray(r.decisionMakers)
    ? r.decisionMakers.filter((dm) => dm && dm.verifiedForBilling === true && dm.email)
    : [];

  const common = {
    domain: r.domain,
    companyName: r.companyName || r.domain,
    hasMx: r.dns?.hasMx ?? false,
    hasSpf: r.dns?.hasSpf ?? false,
    hasDmarc: r.dns?.hasDmarc ?? false,
    emailProvider: r.dns?.emailProvider || null,
    emailPattern: r.emailPattern || null,
    phones: Array.isArray(r.phones) ? r.phones.join(', ') : '',
    companyLinkedin: r.socials?.linkedin || null,
    vatIds: Array.isArray(r.legal?.vatIds) ? r.legal.vatIds.join(', ') : '',
    impressumUrl: r.legal?.impressumUrl || null,
    estimatedChargeUsd: r.billing?.estimatedChargeUsd ?? 0,
    extractedAtUtc: r.extractedAtUtc || null
  };

  if (verifiedDms.length > 0) {
    for (const dm of verifiedDms) {
      rows.push({
        json: {
          ...common,
          recordType: 'decision_maker',
          fullName: dm.fullName,
          role: dm.role,
          email: dm.email,
          emailSource: dm.emailSource,
          linkedinUrl: dm.linkedinUrl || null,
          sourceUrl: dm.sourceUrl || r.sourceUrl || null,
          confidence: dm.confidence
        }
      });
    }
  } else if (r.primaryEmail) {
    rows.push({
      json: {
        ...common,
        recordType: 'company_contact',
        fullName: null,
        role: null,
        email: r.primaryEmail,
        emailSource: r.source || 'published',
        linkedinUrl: null,
        sourceUrl: r.sourceUrl || null,
        confidence: r.confidence ?? 0
      }
    });
  }
}

return rows;
